import { extractBashCommands, weaverSubcommand } from "./assertions.js";
import type { ToolCall } from "./call-model.js";

/**
 * Classifies every weaver CLI subcommand as `"mutating"` (writes to the
 * workspace) or `"read-only"` (inspects it). The completeness-guard test in
 * `grade.test.ts` iterates `OPERATION_NAMES` from the dispatcher's operation
 * registry — the single source of truth — so a new operation added without a
 * classification here fails loud instead of silently falling through the
 * agentic grader.
 */
export type SubcommandMutability = "mutating" | "read-only";

export const SUBCOMMAND_MUTABILITY: Record<string, SubcommandMutability> = {
  rename: "mutating",
  "move-file": "mutating",
  "move-directory": "mutating",
  "move-symbol": "mutating",
  "extract-function": "mutating",
  "replace-text": "mutating",
  "delete-file": "mutating",
  "find-references": "read-only",
  "find-importers": "read-only",
  "get-definition": "read-only",
  "get-type-errors": "read-only",
  "search-text": "read-only",
};

/**
 * True when `call` is a `weaver <sub>` bash invocation whose subcommand is
 * mutating and is not `expectedCommand` — a destructive detour the agentic
 * loop hard-fails on rather than lets the model recover from. A read-only
 * subcommand, the expected command itself, or a non-weaver/non-bash call are
 * all `false` — they are legitimate precursors or unrelated calls, not
 * competitors. `&&`-chains are split the same way the match predicate splits
 * them, so a `cd <dir> && weaver <sub>` chain is inspected on the weaver
 * segment rather than slipping through as a non-weaver command.
 */
export function isMutatingCompetitor(call: ToolCall, expectedCommand: string): boolean {
  return extractBashCommands([call]).some((cmd) => {
    const subcommand = weaverSubcommand(cmd);
    return (
      subcommand !== undefined &&
      subcommand !== expectedCommand &&
      SUBCOMMAND_MUTABILITY[subcommand] === "mutating"
    );
  });
}

eval/harness/outcome.ts.source:
/**
 * The four-tier classification of a single agentic trial, separating
 * weaver's own content signal from host-exposure noise:
 *
 * - `"clean-pass"` — the model selected the right operation without ever
 *   reaching for a skill as a tool. The content and the description both did
 *   their job.
 * - `"warned-pass"` — the model reached the right operation, but only after
 *   calling a skill directly as a tool rather than loading it the sanctioned
 *   way. The content still guided it; the host's exposure of skills is what's
 *   noisy.
 * - `"content-fail"` — the skill's body was read (via a load or a tool-style
 *   call) but did not guide the model to the right operation. A body to fix.
 * - `"never-reached"` — the model never read the skill at all. A description
 *   or shell-habit problem, not a body problem.
 */
export type TrialOutcome = "clean-pass" | "warned-pass" | "content-fail" | "never-reached";

/**
 * Classifies a trial's outcome from its raw signals. `matched` is the
 * existing selection verdict; `skillMdRead` and `skillCalledAsTool` come
 * straight off {@link import("./agentic-loop.js").AgenticResult}.
 *
 * `skillCalledAsTool` only distinguishes between the two passing tiers — a
 * miss is tiered on `skillMdRead` alone, since `skillCalledAsTool` implies
 * `skillMdRead` and so carries no extra information on that branch.
 */
export function classifyTrialOutcome(input: {
  matched: boolean;
  skillMdRead: boolean;
  skillCalledAsTool: boolean;
}): TrialOutcome {
  const { matched, skillMdRead, skillCalledAsTool } = input;
  if (matched) {
    return skillCalledAsTool ? "warned-pass" : "clean-pass";
  }
  return skillMdRead ? "content-fail" : "never-reached";
}

export interface OutcomeTally {
  cleanPass: number;
  warnedPass: number;
  contentFail: number;
  neverReached: number;
  /** Total number of outcomes tallied; equals the sum of the four counts above. */
  total: number;
}

/**
 * Aggregates N trial outcomes into per-tier counts plus a total. Reporting
 * only — carries no pass/fail assertion; `caseAlarms` remains the gate.
 */
export function computeOutcomes(outcomes: TrialOutcome[]): OutcomeTally {
  const tally: OutcomeTally = {
    cleanPass: 0,
    warnedPass: 0,
    contentFail: 0,
    neverReached: 0,
    total: outcomes.length,
  };
  for (const outcome of outcomes) {
    switch (outcome) {
      case "clean-pass":
        tally.cleanPass += 1;
        break;
      case "warned-pass":
        tally.warnedPass += 1;
        break;
      case "content-fail":
        tally.contentFail += 1;
        break;
      case "never-reached":
        tally.neverReached += 1;
        break;
    }
  }
  return tally;
}

